package com.turboio.addon;

import java.lang.reflect.Method;

/** Reflection bridge for the smali hook prepended to the three JNI callbacks of the official AlwaysOnController (1.0.20, non-obfuscated
 * com.rayneo.airuntime.controller package). TurboAddon.ao dispatches here (the smali is generated by package.mjs); every
 * method swallows Throwable so the official callback is never affected, and none blocks. */
final class WhaleCaptureHook {
    private static Method role, round, text, finished;
    private static Class<?> cached;
    private WhaleCaptureHook() {}

    static void response(Object controller, Object response) {
        try {
            if (response == null) return;
            synchronized (WhaleCaptureHook.class) {
                if (cached != response.getClass()) {
                    cached = response.getClass();
                    role = cached.getMethod("getRole"); round = cached.getMethod("getRoundId"); text = cached.getMethod("getText"); finished = cached.getMethod("getFinished");
                }
            }
            Object r = role.invoke(response), id = round.invoke(response), t = text.invoke(response), f = finished.invoke(response);
            WhaleSyncScheduler.onResponse(r instanceof String ? (String) r : null, id instanceof String ? (String) id : null, t instanceof String ? (String) t : null, Boolean.TRUE.equals(f));
        } catch (Throwable ignored) { }
    }
    static void start(Object controller) { try { WhaleSyncScheduler.onStart(); } catch (Throwable ignored) { } }
    static void end(Object controller) { try { WhaleSyncScheduler.onEnd(); } catch (Throwable ignored) { } }
}
